"""Exact calibration model for SyncWise contract 3.1 (port bias inference).

All values are exact integers.  Units: 1ps = 10^6 attoseconds (as), 1ns = 10^9 as.
A drift of v ppb over t ns contributes v*t as.
"""
import numpy as np
from collections import deque

PS = 10 ** 6
NS = 10 ** 9
INF = 10 ** 17          # distance sentinel; true distances are within +-3e14
BIG = 10 ** 40          # combined-key sentinel for unreachable states
AM = 1 << 23            # age multiplier in combined (error, age) keys


def int_ok(x):
    return type(x) is int


def exact_edges(profile):
    """Constraint i: L <= x[b]-x[a] <= U.
    id 2i: a->b weight U ; id 2i+1: b->a weight -L."""
    K = int(profile['groups'])
    E = []
    for i, ms in enumerate(profile['measurements']):
        a = int(ms[0]); b = int(ms[1]); L = int(ms[2]); U = int(ms[3])
        E.append((a, b, U, 2 * i))
        E.append((b, a, -L, 2 * i + 1))
    return K, E


def edge_table(E):
    """constraint id -> (from, to, weight)"""
    tab = {}
    for a, b, w, i in E:
        tab[i] = (a, b, w)
    return tab


def fw_distances(K, E):
    """Floyd-Warshall APSP; returns (D ndarray, feasible bool)."""
    D = np.full((K, K), INF, dtype=np.int64)
    np.fill_diagonal(D, 0)
    for a, b, w, i in E:
        if w < D[a][b]:
            D[a][b] = w
    for k in range(K):
        np.minimum(D, D[:, k][:, None] + D[k][None, :], out=D)
    feasible = not bool((np.diagonal(D) < 0).any())
    return D, feasible


def neg_cycle(K, E):
    """Bellman-Ford extraction of a simple negative cycle (list of ids,
    traversal order, 1..K ids) or None."""
    dist = [0] * K
    pe = [-1] * K
    eby = edge_table(E)
    upd = -1
    for _ in range(K):
        upd = -1
        for a, b, w, i in E:
            nd = dist[a] + w
            if nd < dist[b]:
                dist[b] = nd
                pe[b] = i
                upd = b
        if upd < 0:
            return None
    if upd < 0 or pe[upd] < 0:
        return None
    y = upd
    for _ in range(K):
        e = pe[y]
        if e < 0:
            return None
        y = eby[e][0]
    cyc = []
    cur = y
    while True:
        e = pe[cur]
        if e < 0:
            return None
        cyc.append(e)
        cur = eby[e][0]
        if cur == y:
            break
    if len(cyc) > K:
        return None
    cyc.reverse()
    tot = 0
    prev_to = None
    for e in cyc:
        a, b, w = eby[e]
        if prev_to is not None and a != prev_to:
            return None
        prev_to = b
        tot += w
    if prev_to != eby[cyc[0]][0] or tot >= 0:
        return None
    return cyc


def check_cycle(cyc, K, E):
    """Structural + semantic validation of a proposed negative cycle."""
    if type(cyc) is not list:
        return False
    if not (1 <= len(cyc) <= K):
        return False
    eby = edge_table(E)
    tot = 0
    first = None
    prev_to = None
    for e in cyc:
        if not int_ok(e) or e not in eby:
            return False
        a, b, w = eby[e]
        if first is None:
            first = a
        elif a != prev_to:
            return False
        prev_to = b
        tot += w
    return prev_to == first and tot < 0


def calib_model(profile):
    """One-stop model: returns dict with feasible flag and products.

    feasible:  D (np int64), H (list of lists, as), C (corrections, as)
    infeasible: cycle (list of ids)
    """
    K, E = exact_edges(profile)
    D, feas = fw_distances(K, E)
    if not feas:
        return {'feasible': False, 'K': K, 'cycle': neg_cycle(K, E)}
    jit = [int(v) for v in profile['jitter_ps']]
    Hm = [[0] * K for _ in range(K)]
    Cm = [[0] * K for _ in range(K)]
    Dl = D.tolist()
    for a in range(K):
        Da = Dl[a]
        for b in range(K):
            hi = Da[b]
            lo = -Dl[b][a]
            Hm[a][b] = (hi - lo) * (PS // 2) + (jit[a] + jit[b]) * PS
            Cm[a][b] = (hi + lo) * (PS // 2)
    return {'feasible': True, 'K': K, 'D': D, 'Dl': Dl, 'H': Hm, 'C': Cm, 'E': E}


def calib_artifact(profile, model=None):
    """Publishable calibration certificate (ok or inconsistent)."""
    m = model or calib_model(profile)
    if not m['feasible']:
        return {"status": "inconsistent", "cycle": m['cycle']}
    K = m['K']
    D = m['D']
    Dl = m['Dl']
    EU = np.array([e[0] for e in m['E']], dtype=np.int64)
    EV = np.array([e[1] for e in m['E']], dtype=np.int64)
    EW = np.array([e[2] for e in m['E']], dtype=np.int64)
    EI = [e[3] for e in m['E']]
    pred = []
    for a in range(K):
        Da = D[a]
        tight = np.flatnonzero((Da[EU] + EW) == Da[EV])
        adjF = [[] for _ in range(K)]
        for j in tight:
            j = int(j)
            adjF[int(EU[j])].append((int(EV[j]), EI[j]))
        row = [None] * K
        seen = bytearray(K)
        seen[a] = 1
        dq = deque([a])
        while dq:
            x = dq.popleft()
            for v, eid in adjF[x]:
                if not seen[v]:
                    seen[v] = 1
                    row[v] = eid
                    dq.append(v)
        # connectivity + no negative cycles guarantee full coverage
        pred.append(row)
    return {"status": "ok", "upper_ps": Dl, "pred": pred}


def verify_calib_artifact(profile, art, model=None):
    """Independent validation of a calibration certificate."""
    if type(art) is not dict:
        return False
    K, E = exact_edges(profile)
    m = model or calib_model(profile)
    st = art.get('status')
    if not m['feasible']:
        if st != 'inconsistent':
            return False
        return check_cycle(art.get('cycle'), K, E)
    if st != 'ok':
        return False
    U = art.get('upper_ps')
    pred = art.get('pred')
    if type(U) is not list or len(U) != K:
        return False
    for r in U:
        if type(r) is not list or len(r) != K:
            return False
        for c in r:
            if not int_ok(c):
                return False
    if U != m['Dl']:
        return False
    if type(pred) is not list or len(pred) != K:
        return False
    eby = edge_table(E)
    for a in range(K):
        pa = pred[a]
        if type(pa) is not list or len(pa) != K:
            return False
        if pa[a] is not None:
            return False
        for b in range(K):
            if b == a:
                continue
            eid = pa[b]
            if not int_ok(eid) or eid not in eby:
                return False
            # walk backwards
            cur = b
            total = 0
            seen = {b}
            while cur != a:
                e = pa[cur]
                frm, to, w = eby[e]
                if to != cur:
                    return False
                total += w
                cur = frm
                if cur in seen:
                    return False
                seen.add(cur)
            if total != U[a][b]:
                return False
    return True


def calibrate(profile):
    """Exact calibration hook (replaces legacy stub)."""
    return calib_artifact(profile)
